record.field:
plan = env['res.users']._customer_cleanup_plan(dry_run=True)
lines = []
for entry in plan:
    lines.append("%s: keep %d, remove %d" % (
        entry['login'], len(entry['kept']), len(entry['removed'])))
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Project Customer group cleanup (dry run)',
        'message': '\n'.join(lines) or 'No customers found.',
        'type': 'warning',
        'sticky': True,
    },
}
